//! Minimal terminal size detection for Unix-like systems.
//!
//! This is a small, self-contained implementation that queries the kernel for
//! the window size of a terminal attached to one of the standard streams.

use std::os::fd::{AsFd, AsRawFd, BorrowedFd};

/// Terminal width in columns.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);

/// Terminal height in rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

/// Returns the size of the terminal.
///
/// The standard output, standard error and standard input streams are checked
/// (in that order); the size of the first one that is a terminal is returned.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of(std::io::stdout())
        .or_else(|| terminal_size_of(std::io::stderr()))
        .or_else(|| terminal_size_of(std::io::stdin()))
}

/// Returns the size of the terminal attached to the given file descriptor.
pub fn terminal_size_of<F: AsFd>(fd: F) -> Option<(Width, Height)> {
    let fd: BorrowedFd<'_> = fd.as_fd();
    let raw = fd.as_raw_fd();
    // SAFETY: `winsize` is a plain C struct; zero-initialisation is valid.
    let mut ws: libc::winsize = unsafe { std::mem::zeroed() };
    // SAFETY: TIOCGWINSZ writes into the provided `winsize` struct only.
    let ret = unsafe { libc::ioctl(raw, libc::TIOCGWINSZ, &mut ws as *mut libc::winsize) };
    if ret != 0 {
        return None;
    }
    if ws.ws_col == 0 || ws.ws_row == 0 {
        return None;
    }
    Some((Width(ws.ws_col), Height(ws.ws_row)))
}
EOF
