//! Mapping of byte values to the characters shown in the character panel.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CharacterTable {
    Default,
    Ascii,
    Codepage1047,
    Codepage437,
    Braille,
}

impl CharacterTable {
    pub fn from_name(name: &str) -> Option<Self> {
        Some(match name {
            "default" => CharacterTable::Default,
            "ascii" => CharacterTable::Ascii,
            "codepage-1047" => CharacterTable::Codepage1047,
            "codepage-437" => CharacterTable::Codepage437,
            "braille" => CharacterTable::Braille,
            _ => return None,
        })
    }

    /// Returns the character used to represent `byte` in the character panel.
    pub fn render(self, byte: u8) -> char {
        match self {
            CharacterTable::Default => match byte {
                0x00 => '\u{22c4}',
                0x20 => ' ',
                0x09 | 0x0a | 0x0c | 0x0d => '_',
                0x21..=0x7e => byte as char,
                0x01..=0x7f => '\u{2022}',
                _ => '\u{d7}',
            },
            CharacterTable::Ascii => match byte {
                0x20..=0x7e => byte as char,
                _ => '.',
            },
            CharacterTable::Codepage1047 => CP1047[byte as usize],
            CharacterTable::Codepage437 => CP437[byte as usize],
            CharacterTable::Braille => match byte {
                0x00 => '\u{22c4}',
                0x09 => '\u{2192}',
                0x0a => '\u{21b5}',
                0x0d => '\u{2190}',
                0x20..=0x7e => byte as char,
                _ => braille(byte),
            },
        }
    }
}

/// Maps the bits of a byte onto the dots of a braille pattern.
fn braille(byte: u8) -> char {
    let b = |mask: u8| byte & mask != 0;
    let mut pattern: u32 = 0;
    if b(0x01) {
        pattern |= 0x01;
    }
    if b(0x02) {
        pattern |= 0x08;
    }
    if b(0x04) {
        pattern |= 0x02;
    }
    if b(0x08) {
        pattern |= 0x10;
    }
    if b(0x10) {
        pattern |= 0x04;
    }
    if b(0x20) {
        pattern |= 0x20;
    }
    if b(0x40) {
        pattern |= 0x40;
    }
    if b(0x80) {
        pattern |= 0x80;
    }
    char::from_u32(0x2800 + pattern).unwrap_or('?')
}

