//! Colors used for the different byte categories, including the environment
//! based overrides and the "gradient" color scheme.

use std::env;

/// Escape sequence resetting the foreground color.
pub const RESET: &str = "\x1b[39m";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ByteCategory {
    Null,
    AsciiPrintable,
    AsciiWhitespace,
    AsciiOther,
    NonAscii,
}

impl ByteCategory {
    pub fn of(byte: u8) -> Self {
        match byte {
            0x00 => ByteCategory::Null,
            0x09 | 0x0a | 0x0c | 0x0d | 0x20 => ByteCategory::AsciiWhitespace,
            0x21..=0x7e => ByteCategory::AsciiPrintable,
            0x01..=0x7f => ByteCategory::AsciiOther,
            _ => ByteCategory::NonAscii,
        }
    }
}

/// A foreground color, together with the exact escape sequence that is used
/// to switch to it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Color {
    escape: String,
}

impl Color {
    pub fn ansi(code: u8) -> Self {
        Color {
            escape: format!("\x1b[{}m", code),
        }
    }

    pub fn rgb(r: u8, g: u8, b: u8) -> Self {
        Color {
            escape: format!("\x1b[38;2;{};{};{}m", r, g, b),
        }
    }

    /// RGB color as emitted by the gradient scheme (zero padded components).
    pub fn rgb_padded(r: u8, g: u8, b: u8) -> Self {
        Color {
            escape: format!("\x1b[38;2;{:03};{:03};{:03}m", r, g, b),
        }
    }

    pub fn escape(&self) -> &str {
        &self.escape
    }

    /// Parses a color specification as accepted in the `HEXYL_COLOR_*`
    /// environment variables.
    pub fn parse(spec: &str) -> Option<Self> {
        if let Some(hex) = spec.strip_prefix('#') {
            if hex.len() != 6 || !hex.chars().all(|c| c.is_ascii_hexdigit()) {
                return None;
            }
            let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
            return Some(Color::rgb(r, g, b));
        }
        let (bright, name) = match spec.strip_prefix("bright ") {
            Some(rest) => (true, rest),
            None => (false, spec),
        };
        let base = match name {
            "black" => 30,
            "red" => 31,
            "green" => 32,
            "yellow" => 33,
            "blue" => 34,
            "magenta" => 35,
            "purple" if !bright => 35,
            "cyan" => 36,
            "white" => 37,
            _ => return None,
        };
        Some(Color::ansi(if bright { base + 60 } else { base }))
    }
}

/// The set of colors used for the default color scheme.
#[derive(Debug, Clone)]
pub struct Palette {
    pub null: Color,
    pub ascii_printable: Color,
    pub ascii_whitespace: Color,
    pub ascii_other: Color,
    pub non_ascii: Color,
    pub offset: Color,
}

impl Palette {
    /// The default palette, with overrides taken from the environment.
    pub fn from_env() -> Self {
        let pick = |var: &str, default: Color| -> Color {
            env::var(var)
                .ok()
                .and_then(|value| Color::parse(&value))
                .unwrap_or(default)
        };
        Palette {
            null: pick("HEXYL_COLOR_NULL", Color::ansi(90)),
            ascii_printable: pick("HEXYL_COLOR_ASCII_PRINTABLE", Color::ansi(36)),
            ascii_whitespace: pick("HEXYL_COLOR_ASCII_WHITESPACE", Color::ansi(32)),
            ascii_other: pick("HEXYL_COLOR_ASCII_OTHER", Color::ansi(32)),
            non_ascii: pick("HEXYL_COLOR_NONASCII", Color::ansi(33)),
            offset: pick("HEXYL_COLOR_OFFSET", Color::ansi(90)),
        }
    }

    pub fn for_category(&self, category: ByteCategory) -> &Color {
        match category {
            ByteCategory::Null => &self.null,
            ByteCategory::AsciiPrintable => &self.ascii_printable,
            ByteCategory::AsciiWhitespace => &self.ascii_whitespace,
            ByteCategory::AsciiOther => &self.ascii_other,
            ByteCategory::NonAscii => &self.non_ascii,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColorScheme {
    Default,
    Gradient,
}

impl ColorScheme {
    pub fn from_name(name: &str) -> Option<Self> {
        Some(match name {
            "default" => ColorScheme::Default,
            "gradient" => ColorScheme::Gradient,
            _ => return None,
        })
    }
}

/// Pre-computed colors for every byte value.
pub struct ByteColors {
    colors: Vec<Color>,
    pub offset: Color,
