//! Terminal related helpers: color support detection and terminal width.

use std::env;
use std::io::IsTerminal;

/// Determines whether colors should be used for `--color=auto`.
///
/// The decision follows the usual conventions: `FORCE_COLOR` and
/// `CLICOLOR_FORCE` force colors on (or off), `NO_COLOR` disables them, and
/// otherwise colors are only used if standard output is a terminal that is
/// known to support them.
pub fn stdout_supports_color() -> bool {
    let force = env_force_color();
    if force > 0 {
        return true;
    }
    if env_no_color() || !std::io::stdout().is_terminal() || env_var_is("TERM", "dumb") {
        return false;
    }
    if env_var_is("COLORTERM", "truecolor") || env_var_is("TERM_PROGRAM", "iTerm.app") {
        return true;
    }
    if env_var_is("TERM_PROGRAM", "Apple_Terminal") || check_256_color(env::var("TERM").ok().as_deref()) {
        return true;
    }
    check_ansi_color(env::var("TERM").ok().as_deref())
        || env::var_os("COLORTERM").is_some()
        || env::var("CLICOLOR").map_or(false, |v| v != "0")
        || is_ci()
}

fn env_var_is(name: &str, expected: &str) -> bool {
    env::var(name).map(|v| v == expected).unwrap_or(false)
}

fn env_force_color() -> usize {
    if let Ok(force) = env::var("FORCE_COLOR") {
        match force.as_str() {
            "true" | "" => 1,
            "false" => 0,
            other => std::cmp::min(other.parse().unwrap_or(1), 3),
        }
    } else if let Ok(force) = env::var("CLICOLOR_FORCE") {
        if force != "0" {
            1
        } else {
            0
        }
    } else {
        0
    }
}

fn env_no_color() -> bool {
    match env::var("NO_COLOR") {
        Ok(value) => value != "0",
        Err(_) => false,
    }
}

fn check_ansi_color(term: Option<&str>) -> bool {
    match term {
        Some(term) => term != "dumb",
        None => false,
    }
}

fn check_256_color(term: Option<&str>) -> bool {
    match term {
        Some(term) => term.ends_with("256") || term.ends_with("256color"),
