//! Parsing of byte counts/offsets such as `64`, `4KiB`, `0xff` or `-2blocks`.

use anyhow::{anyhow, bail, Context, Result};

/// Sign of a parsed offset. `-0` is distinct from `0`: it seeks relative to
/// the end of the input.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Sign {
    Positive,
    Negative,
}

/// A parsed byte offset: a non-negative magnitude plus an explicit sign.
#[derive(Debug, Clone, Copy)]
pub struct ByteOffset {
    pub sign: Sign,
    pub magnitude: i64,
}

impl ByteOffset {
    /// Interprets the offset as a count, rejecting negative values.
    pub fn as_count(&self) -> Result<i64> {
        match self.sign {
            Sign::Positive => Ok(self.magnitude),
            Sign::Negative => bail!(
                "negative offset specified, but only positive offsets (counts) are accepted in this context"
            ),
        }
    }
}

/// Parses an offset with an optional leading sign.
pub fn parse_byte_offset(input: &str, block_size: i64) -> Result<ByteOffset> {
    let first = match input.chars().next() {
        Some(c) => c,
        None => bail!("no character data found, did you forget to write it?"),
    };
    let (sign, rest) = match first {
        '+' => (Sign::Positive, &input[1..]),
        '-' => (Sign::Negative, &input[1..]),
        _ => (Sign::Positive, input),
    };
    if rest.is_empty() {
        bail!("no digits found after sign, did you forget to write them?");
    }
    let magnitude = parse_count(rest, Some(block_size))?;
    Ok(ByteOffset { sign, magnitude })
}

/// Result of parsing a `--block-size` argument.
pub enum BlockSize {
    /// A regular, positive block size.
    Size(i64),
    /// A block size given as a hex number. The original tool stops processing
    /// (successfully) in this case, so callers must treat it specially.
    HexSpecified,
}

/// Parses a `--block-size` argument. No sign is allowed and the `block` unit
/// cannot be used.
pub fn parse_block_size(input: &str) -> Result<BlockSize> {
    if input.is_empty() {
        bail!("no character data found, did you forget to write it?");
    }
    if let Some(hex) = input.strip_prefix("0x") {
        parse_hex(hex)?;
        return Ok(BlockSize::HexSpecified);
    }
    let size = parse_count(input, None)?;
    if size <= 0 {
        bail!("block size argument must be positive");
    }
    Ok(BlockSize::Size(size))
}

fn parse_hex(hex: &str) -> Result<i64> {
    if let Some(c) = hex.chars().next() {
        if c == '+' || c == '-' {
            bail!(
                "found '{}' sign after hex prefix (\"0x\"); signs should go before it",
                c
            );
        }
    }
    i64::from_str_radix(hex, 16).context("failed to parse integer part")
}

/// Parses `<pos-integer>[<unit>]` (or a `0x` prefixed hex number).
///
/// `block_size` is `None` when the `block(s)` unit is not permitted.
fn parse_count(input: &str, block_size: Option<i64>) -> Result<i64> {
    if let Some(hex) = input.strip_prefix("0x") {
        return parse_hex(hex);
    }
    let digits_end = input
        .find(|c: char| !c.is_ascii_digit())
        .unwrap_or(input.len());
    if digits_end == 0 {
        bail!(
            "{:?} is not of the expected form <pos-integer>[<unit>]",
            input
        );
    }
    let (number, unit) = input.split_at(digits_end);
    let number: i64 = number.parse().context("failed to parse integer part")?;
    let multiplier: i64 = match unit.to_lowercase().as_str() {
        "" => 1,
        "kb" => 1_000,
        "mb" => 1_000_000,
        "gb" => 1_000_000_000,
        "tb" => 1_000_000_000_000,
        "kib" => 1 << 10,
        "mib" => 1 << 20,
        "gib" => 1 << 30,
        "tib" => 1 << 40,
        "block" | "blocks" => match block_size {
            Some(size) => size,
            None => bail!("can not use 'block(s)' as a unit to specify block size"),
        },
        _ => bail!("invalid unit {:?}", unit),
    };
    number.checked_mul(multiplier).ok_or_else(|| {
        anyhow!(
            "count multiplied by the unit overflowed a signed 64-bit integer; are you sure it should be that big?"
        )
    })
}
