//! Input abstraction over a file or standard input.

use std::fs::File;
use std::io::{self, Read, Seek, SeekFrom, StdinLock};

pub enum Input<'a> {
    File(File),
    Stdin(StdinLock<'a>),
}

impl<'a> Read for Input<'a> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match self {
            Input::File(file) => file.read(buf),
            Input::Stdin(stdin) => stdin.read(buf),
        }
    }
}

impl<'a> Seek for Input<'a> {
    fn seek(&mut self, pos: SeekFrom) -> io::Result<u64> {
        match self {
            Input::File(file) => file.seek(pos),
            Input::Stdin(stdin) => {
                // Standard input cannot be positioned; the best we can do is
                // to read and discard data when seeking forward.
                let amount = match pos {
                    SeekFrom::Start(n) => n,
                    SeekFrom::Current(n) if n >= 0 => n as u64,
                    _ => {
                        return Err(io::Error::new(
                            io::ErrorKind::Unsupported,
                            "cannot seek backwards or relative to the end on stdin",
                        ))
                    }
                };
                let discarded = io::copy(&mut stdin.by_ref().take(amount), &mut io::sink())?;
                Ok(discarded)
            }
        }
    }
}
