            "b" | "bin" | "binary" | "2" => Base::Binary,
            "o" | "oct" | "octal" | "8" => Base::Octal,
            "d" | "dec" | "decimal" | "10" => Base::Decimal,
            "x" | "hex" | "hexadecimal" | "16" => Base::Hexadecimal,
            _ => return None,
        })
    }

    /// Number of characters needed for one byte.
    pub fn digits(self) -> usize {
        match self {
            Base::Binary => 8,
            Base::Octal => 3,
            Base::Decimal => 3,
            Base::Hexadecimal => 2,
        }
    }

    fn format(self, byte: u8, out: &mut String) {
        use std::fmt::Write as _;
        match self {
            Base::Binary => write!(out, "{:08b}", byte),
            Base::Octal => write!(out, "{:03o}", byte),
            Base::Decimal => write!(out, "{:03}", byte),
            Base::Hexadecimal => write!(out, "{:02x}", byte),
        }
        .expect("writing to a String cannot fail");
    }
}

/// Everything that influences how the dump is rendered.
pub struct PrinterConfig {
    pub show_color: bool,
    pub show_char_panel: bool,
    pub show_position_panel: bool,
    pub border: BorderStyle,
    pub squeeze: bool,
    pub table: CharacterTable,
    pub colors: ByteColors,
    pub panels: usize,
    pub group_size: usize,
    pub little_endian: bool,
    pub base: Base,
    /// Position shown for the first byte of the output.
    pub start_position: u64,
}

/// Width (in characters) of the data part of one hex panel.
pub fn hex_panel_width(base: Base, group_size: usize) -> usize {
    8 * base.digits() + (8 / group_size - 1)
}

pub struct Printer<W: Write> {
    writer: W,
    cfg: PrinterConfig,
    line_width: usize,
    hex_width: usize,
    position: u64,
    /// Byte value if the previous complete line consisted of a single value.
    prev_uniform: Option<u8>,
    last_was_squeezed: bool,
    /// Reusable output buffer for one line.
    line_out: String,
}

impl<W: Write> Printer<W> {
    pub fn new(writer: W, cfg: PrinterConfig) -> Self {
        let line_width = 8 * cfg.panels;
        let hex_width = hex_panel_width(cfg.base, cfg.group_size);
        let position = cfg.start_position;
        Printer {
            writer,
            cfg,
            line_width,
            hex_width,
            position,
            prev_uniform: None,
            last_was_squeezed: false,
            line_out: String::new(),
        }
    }

    fn write_rule(&mut self, (left, middle, right): (&str, &str, &str)) -> io::Result<()> {
        if self.cfg.border == BorderStyle::None {
            return Ok(());
        }
        let dash = self.cfg.border.horizontal();
        let mut s = String::new();
        s.push_str(left);
        if self.cfg.show_position_panel {
            s.push_str(&dash.repeat(8));
            s.push_str(middle);
        }
        for i in 0..self.cfg.panels {
            s.push_str(&dash.repeat(self.hex_width + 2));
            if i + 1 < self.cfg.panels || self.cfg.show_char_panel {
                s.push_str(middle);
            }
        }
        if self.cfg.show_char_panel {
            for i in 0..self.cfg.panels {
                s.push_str(&dash.repeat(8));
                if i + 1 < self.cfg.panels {
                    s.push_str(middle);
                }
            }
        }
        s.push_str(right);
        s.push('\n');
        self.writer.write_all(s.as_bytes())
    }

    pub fn header(&mut self) -> io::Result<()> {
        let top = self.cfg.border.top();
        self.write_rule(top)
    }

    pub fn footer(&mut self) -> io::Result<()> {
        let bottom = self.cfg.border.bottom();
        self.write_rule(bottom)
    }

    /// The line shown when the input did not contain any data.
    fn no_content(&mut self) -> io::Result<()> {
        let width = 8 * 2 + (8 / self.cfg.group_size - 1) + 2;
        let mut s = String::from("│");
        if self.cfg.show_position_panel {
            s.push_str("        │");
        }
        s.push_str(" No content");
        s.push_str(&" ".repeat(width.saturating_sub(11)));
        s.push('│');
        s.push_str(&" ".repeat(width));
        if self.cfg.show_char_panel {
            s.push_str("│        │        ");
        }
        s.push_str("│\n");
        self.writer.write_all(s.as_bytes())
    }

    /// Writes the start of a line: left border and position panel.
    fn write_prefix(&mut self, marker: bool) {
        let out = &mut self.line_out;
        out.push_str(self.cfg.border.outer());
        if self.cfg.show_color {
            out.push_str(self.cfg.colors.offset.escape());
        }
        if self.cfg.show_position_panel {
            if marker {
                out.push('*');
                if self.cfg.show_color {
                    out.push_str(RESET);
                }
                out.push_str("       ");
            } else {
                use std::fmt::Write as _;
                write!(out, "{:08x}", self.position).expect("writing to a String cannot fail");
                if self.cfg.show_color {
                    out.push_str(RESET);
                }
            }
            out.push_str(self.cfg.border.outer());
        }
    }

    fn write_hex_panel(&mut self, bytes: &[u8]) {
        let mut written = 0;
        let mut current: Option<&Color> = None;
        let mut text = String::new();
        for (gi, group) in bytes.chunks(self.cfg.group_size).enumerate() {
            if gi > 0 {
                text.push(' ');
                written += 1;
            }
            let ordered: Vec<u8> = if self.cfg.little_endian {
                group.iter().rev().copied().collect()
            } else {
                group.to_vec()
            };
            for b in ordered {
                if self.cfg.show_color {
                    let color = self.cfg.colors.get(b);
                    if current != Some(color) {
                        text.push_str(color.escape());
                        current = Some(color);
                    }
                }
                self.cfg.base.format(b, &mut text);
                written += self.cfg.base.digits();
            }
        }
        self.line_out.push_str(&text);
        if written < self.hex_width {
            self.line_out.push_str(&" ".repeat(self.hex_width - written));
        }
    }

    fn write_char_panel(&mut self, bytes: &[u8]) {
        let mut current: Option<&Color> = None;
        let mut text = String::new();
        for &b in bytes {
            if self.cfg.show_color {
                let color = self.cfg.colors.get(b);
                if current != Some(color) {
                    text.push_str(color.escape());
                    current = Some(color);
                }
            }
            text.push(self.cfg.table.render(b));
        }
        self.line_out.push_str(&text);
        if bytes.len() < 8 {
            self.line_out.push_str(&" ".repeat(8 - bytes.len()));
        }
    }

    /// Writes one line of output. `marker` selects the squeeze indicator line.
    fn write_line(&mut self, bytes: &[u8], marker: bool) -> io::Result<()> {
        self.line_out.clear();
        self.write_prefix(marker);

        for i in 0..self.cfg.panels {
            if marker && i == 0 && !self.cfg.show_position_panel {
                if self.cfg.show_color {
                    self.line_out.push_str(self.cfg.colors.offset.escape());
                }
                self.line_out.push('*');
                if self.cfg.show_color {
                    self.line_out.push_str(RESET);
                }
            } else {
                self.line_out.push(' ');
            }
            let start = (i * 8).min(bytes.len());
            let end = ((i + 1) * 8).min(bytes.len());
            if marker {
                self.line_out.push_str(&" ".repeat(self.hex_width));
            } else {
                self.write_hex_panel(&bytes[start..end]);
            }
            if self.cfg.show_color {
                self.line_out.push_str(RESET);
            }
            self.line_out.push(' ');
            if i + 1 < self.cfg.panels {
                self.line_out.push_str(self.cfg.border.inner());
            } else {
                self.line_out.push_str(self.cfg.border.outer());
            }
        }

        if self.cfg.show_char_panel {
            for i in 0..self.cfg.panels {
                let start = (i * 8).min(bytes.len());
                let end = ((i + 1) * 8).min(bytes.len());
                if marker {
                    self.line_out.push_str("        ");
                } else {
                    self.write_char_panel(&bytes[start..end]);
                }
                if self.cfg.show_color {
                    self.line_out.push_str(RESET);
                }
                if i + 1 < self.cfg.panels {
                    self.line_out.push_str(self.cfg.border.inner());
                } else {
                    self.line_out.push_str(self.cfg.border.outer());
                }
            }
        }
        self.line_out.push('\n');
        let out = std::mem::take(&mut self.line_out);
        let result = self.writer.write_all(out.as_bytes());
        self.line_out = out;
        result
    }

    /// Handles one complete line of input.
    fn process_line(&mut self, line: &[u8]) -> io::Result<()> {
        let uniform = if line.iter().all(|&b| b == line[0]) {
            Some(line[0])
        } else {
            None
        };
        let squeezable = self.cfg.squeeze && uniform.is_some() && self.prev_uniform == uniform;
        if squeezable {
            if !self.last_was_squeezed {
                self.write_line(&[], true)?;
            }
            self.last_was_squeezed = true;
        } else {
            self.write_line(line, false)?;
            self.last_was_squeezed = false;
        }
        self.prev_uniform = uniform;
        self.position = self.position.wrapping_add(line.len() as u64);
        Ok(())
    }

    pub fn print_all<R: Read>(&mut self, mut reader: R) -> io::Result<()> {
        self.header()?;

        let mut buffer = vec![0u8; self.line_width];
        let mut line: Vec<u8> = Vec::with_capacity(self.line_width);
        let mut first_read = true;
        let mut is_empty = true;

        loop {
            let size = match reader.read(&mut buffer) {
                Ok(0) => break,
                Ok(n) => n,
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(_) => {
                    // Mirror the behaviour of the reference implementation:
                    // a failing read at a line boundary re-uses the buffer
                    // contents, otherwise the read is simply retried.
                    if line.is_empty() {
                        buffer.len()
                    } else {
                        continue;
                    }
                }
            };
            is_empty = false;
            for &b in &buffer[..size] {
                line.push(b);
                if line.len() == self.line_width {
                    let full = std::mem::take(&mut line);
                    self.process_line(&full)?;
                    line = full;
                    line.clear();
                }
            }
            if first_read {
                self.writer.flush()?;
                first_read = false;
            }
        }

        if is_empty {
            self.no_content()?;
        } else if !line.is_empty() {
            self.write_line(&line, false)?;
            self.position = self.position.wrapping_add(line.len() as u64);
        } else if self.last_was_squeezed {
            if self.cfg.show_position_panel {
                self.write_line(&[], false)?;
            } else {
                self.write_line(&[], true)?;
            }
        }

        self.footer()?;
        self.writer.flush()
    }
}

/// Converts a file name into a C identifier the same way `xxd -i` does.
pub fn include_identifier(name: &str) -> String {
    name.chars()
        .map(|c| if c.is_alphanumeric() { c } else { '_' })
        .collect()
}

/// Writes the input in C include file style.
pub fn print_include<R: Read, W: Write>(
    mut reader: R,
    writer: &mut W,
    name: Option<&str>,
) -> io::Result<()> {
    let ident = name.map(include_identifier);
    if let Some(ident) = &ident {
        writeln!(writer, "unsigned char {}[] = {{", ident)?;
    }
    let mut count: u64 = 0;
    let mut buffer = [0u8; 8192];
    loop {
        let size = match reader.read(&mut buffer) {
            Ok(0) => break,
            Ok(n) => n,
            Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e),
        };
        let mut chunk = String::new();
        for &b in &buffer[..size] {
            use std::fmt::Write as _;
            if count % 12 == 0 {
                if count > 0 {
                    chunk.push_str(",\n");
                }
                chunk.push_str("  ");
            } else {
                chunk.push_str(", ");
            }
            write!(chunk, "0x{:02x}", b).expect("writing to a String cannot fail");
            count += 1;
        }
        writer.write_all(chunk.as_bytes())?;
    }
    writeln!(writer)?;
    if let Some(ident) = &ident {
        writeln!(writer, "}};")?;
        writeln!(writer, "unsigned int {}_len = {};", ident, count)?;
    }
    Ok(())
}
EOF
