fn print_color_table(palette: &Palette) -> io::Result<()> {
    let mut out = String::from("hexyl color reference:\n\n");
    let entries = [
        (&palette.null, "⋄ NULL bytes (0x00)"),
        (
            &palette.ascii_printable,
            "a ASCII printable characters (0x20 - 0x7E)",
        ),
        (
            &palette.ascii_whitespace,
            "_ ASCII whitespace (0x09 - 0x0D, 0x20)",
        ),
        (
            &palette.ascii_other,
            "• ASCII control characters (except NULL and whitespace)",
        ),
        (&palette.non_ascii, "× Non-ASCII bytes (0x80 - 0xFF)"),
    ];
    for (color, text) in entries {
        out.push_str(color.escape());
        out.push_str(text);
        out.push('\n');
        out.push_str(RESET);
    }
    let stdout = io::stdout();
    let mut handle = stdout.lock();
    handle.write_all(out.as_bytes())?;
    handle.flush()
}

fn given_on_command_line(matches: &clap::ArgMatches, id: &str) -> bool {
    matches.value_source(id) == Some(ValueSource::CommandLine)
}

fn run() -> Result<()> {
    let matches = build_command().get_matches();

    if let Some(shell) = matches.get_one::<Shell>("completion") {
        let mut cmd = build_command();
        clap_complete::generate(*shell, &mut cmd, "hexyl", &mut io::stdout());
        return Ok(());
    }

    let palette = Palette::from_env();

    if matches.get_flag("print_color_table") {
        print_color_table(&palette)?;
        return Ok(());
    }

    let stdin = io::stdin();
    let mut reader = match matches.get_one::<String>("file") {
        Some(filename) => {
            let file = File::open(filename)?;
            if file.metadata()?.is_dir() {
                bail!("'{}' is a directory.", filename);
            }
            Input::File(file)
        }
        None => Input::Stdin(stdin.lock()),
    };

    let block_size = match parse_block_size(
        matches
            .get_one::<String>("block_size")
            .map(String::as_str)
            .unwrap_or("512"),
    )? {
        BlockSize::Size(size) => size,
        // The reference implementation stops right here for hex block sizes.
        BlockSize::HexSpecified => return Ok(()),
    };

    let skip_offset: u64 = match matches.get_one::<String>("skip") {
        Some(skip) => {
            let offset = parse_byte_offset(skip, block_size)
                .with_context(|| format!("failed to parse `--skip` arg {:?} as byte count", skip))?;
            let target = match offset.sign {
                Sign::Positive => SeekFrom::Start(offset.magnitude as u64),
                Sign::Negative => SeekFrom::End(-offset.magnitude),
            };
            reader.seek(target).map_err(|_| {
                anyhow!("Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).")
            })?
        }
        None => 0,
    };

    let length: Option<u64> = match matches.get_one::<String>("length") {
        Some(length) => Some(
            parse_byte_offset(length, block_size)
                .and_then(|offset| offset.as_count())
                .with_context(|| {
                    format!("failed to parse `--length` arg {:?} as byte count", length)
                })? as u64,
        ),
        None => None,
    };

    let display_offset: u64 = {
        let value = matches
            .get_one::<String>("display_offset")
            .map(String::as_str)
            .unwrap_or("0");
        parse_byte_offset(value, block_size)
            .and_then(|offset| offset.as_count())
            .with_context(|| {
                format!(
                    "failed to parse `--display-offset` arg {:?} as byte count",
                    value
                )
            })? as u64
    };

    let base = Base::from_name(
        matches
            .get_one::<String>("base")
            .map(String::as_str)
            .unwrap_or("hexadecimal"),
    )
    .ok_or_else(|| {
        anyhow!("The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\".")
    })?;

    let plain = matches.get_flag("plain");
    let show_char_panel = !plain && !matches.get_flag("no_chars");
    let show_position_panel = !plain && !matches.get_flag("no_position");

    let border = if plain && !given_on_command_line(&matches, "border") {
        BorderStyle::None
    } else {
        BorderStyle::from_name(
            matches
                .get_one::<String>("border")
                .map(String::as_str)
                .unwrap_or("unicode"),
        )
        .unwrap_or(BorderStyle::Unicode)
    };

    let show_color = if plain && !given_on_command_line(&matches, "color") {
        false
    } else {
        match matches
            .get_one::<String>("color")
            .map(String::as_str)
            .unwrap_or("always")
        {
            "always" => std::env::var_os("NO_COLOR").is_none(),
            "auto" => std::env::var_os("NO_COLOR").is_none() && term::stdout_supports_color(),
            "force" => true,
            _ => false,
        }
    };

    let table = CharacterTable::from_name(
        matches
            .get_one::<String>("character_table")
            .map(String::as_str)
            .unwrap_or("default"),
    )
    .unwrap_or(CharacterTable::Default);

    let scheme = ColorScheme::from_name(
        matches
            .get_one::<String>("color_scheme")
            .map(String::as_str)
            .unwrap_or("default"),
    )
    .unwrap_or(ColorScheme::Default);

    let group_size: usize = matches
        .get_one::<String>("group_size")
        .and_then(|g| g.parse().ok())
        .unwrap_or(1);

    let little_endian = if matches.get_flag("little_endian_format") {
        true
    } else {
        matches
            .get_one::<String>("endianness")
            .map(|e| e == "little")
            .unwrap_or(false)
    };

    let hex_width = hex_panel_width(base, group_size);
    let panels_for_width = |width: usize| -> usize {
        let per_panel = hex_width + 3 + if show_char_panel { 8 } else { 0 };
        let fixed = 1 + if show_position_panel { 9 } else { 0 };
        (width.saturating_sub(fixed) / per_panel).max(1)
    };

    let panels: usize = if let Some(width) = matches.get_one::<NonZeroU64>("terminal_width") {
        panels_for_width(width.get() as usize)
    } else if let Some(panels) = matches.get_one::<String>("panels") {
        if panels == "auto" {
            panels_for_width(term::terminal_width().unwrap_or(80))
        } else {
            panels
                .parse::<NonZeroU64>()
                .with_context(|| {
                    format!(
                        "failed to parse `--panels` arg {:?} as unsigned nonzero integer",
                        panels
                    )
                })?
                .get() as usize
        }
    } else {
        panels_for_width(term::terminal_width().unwrap_or(80)).min(2)
    };

    let stdout = io::stdout();
    let mut writer = BufWriter::new(stdout.lock());

    let reader: Box<dyn Read> = match length {
        Some(length) => Box::new(reader.take(length)),
        None => Box::new(reader),
    };

    if matches.get_flag("include") {
        let name = matches.get_one::<String>("file").and_then(|f| {
            std::path::Path::new(f)
                .file_name()
                .map(|n| n.to_string_lossy().into_owned())
        });
        print_include(reader, &mut writer, name.as_deref())?;
        writer.flush()?;
        return Ok(());
    }

    let cfg = PrinterConfig {
        show_color,
        show_char_panel,
        show_position_panel,
        border,
        squeeze: !matches.get_flag("no_squeezing"),
        table,
        colors: ByteColors::new(scheme, &palette),
        panels,
        group_size,
        little_endian,
        base,
        start_position: skip_offset.wrapping_add(display_offset),
    };
    let mut printer = Printer::new(&mut writer, cfg);
    printer.print_all(reader)?;
    Ok(())
}

fn main() {
    if let Err(err) = run() {
        let broken_pipe = err
            .chain()
            .any(|cause| {
                cause
                    .downcast_ref::<io::Error>()
                    .map(|e| e.kind() == io::ErrorKind::BrokenPipe)
                    .unwrap_or(false)
            });
        if broken_pipe {
            std::process::exit(0);
        }
        eprintln!("Error: {:?}", err);
        std::process::exit(1);
    }
}
