//! Input abstraction over a file or standard input.

use std::fs::File;
use std::io::{self, Read, Seek, SeekFrom, StdinLock};

pub enum Input<'a> {
    File(File),
    Stdin(StdinLock<'a>),
}

impl<'a> Read for Input<'a> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match self {
            Input::File(file) => file.read(buf),
            Input::Stdin(stdin) => stdin.read(buf),
        }
    }
}

/// Amount of bytes to skip forward for a seek position, if the position can
/// be reached by simply reading (and discarding) data.
fn forward_amount(pos: SeekFrom) -> Option<u64> {
    match pos {
        SeekFrom::Start(n) => Some(n),
        SeekFrom::Current(n) if n >= 0 => Some(n as u64),
        _ => None,
    }
}

/// Skips `amount` bytes by reading and discarding them. Returns the number of
/// bytes that were actually skipped (less if the input ended early).
fn discard<R: Read>(reader: &mut R, amount: u64) -> io::Result<u64> {
    io::copy(&mut reader.take(amount), &mut io::sink())
}

impl<'a> Seek for Input<'a> {
    fn seek(&mut self, pos: SeekFrom) -> io::Result<u64> {
        match self {
            Input::File(file) => match file.seek(pos) {
                Ok(position) => Ok(position),
                // Files that are not seekable (e.g. named pipes) can still be
                // skipped forward by reading.
                Err(err) => match forward_amount(pos) {
                    Some(amount) => discard(file, amount),
                    None => Err(err),
                },
            },
